style.css:
/* 设置网页背景为护眼绿色（豆沙绿） */
body, html {
    background-color: #C7EDCC !important; /* 豆沙绿色 */
    color: #000000 !important; /* 确保文本颜色为黑色以增强可读性 */
}

/* 覆盖所有主要内容区域的背景 */
div, section, main, aside, footer, header, nav, article {
    background-color: #C7EDCC !important;
    color: #000000 !important;
}

/* 修改输入框和按钮的背景颜色 */
input, textarea, select, button {
    background-color: #E6F4E6 !important; /* 较浅的绿色，保持对比 */
    color: #000000 !important;
    border: 1px solid #AACBB2 !important; /* 边框为浅绿色 */
}

/* 针对表格和列表的背景色调整 */
table, th, td, ul, ol, li {
    background-color: #C7EDCC !important;
    color: #000000 !important;
}

/* 覆盖标题栏和标签栏的背景颜色 */
h1, h2, h3, h4, h5, h6 {
    background-color: #B8DCC4 !important; /* 较深的护眼绿 */
    color: #000000 !important;
}

/* 针对链接和交互元素的颜色调整 */
a {
    color: #3A6F41 !important; /* 深绿色，增强可读性 */
}

/* 确保代码块和预格式化文本背景一致 */
pre, code {
    background-color: #E1F1E1 !important;
    color: #000000 !important;
}
